from collections import Counter
web = [("1.1.1.1", 500)] * 4 + [("1.1.1.1", 400)] * 12 + [("10.0.0.5", 500)] * 3 + [("10.0.0.9", 200)] * 50
ips_hits = {"1.1.1.1"}  # 앞단 IPS 시그니처에 걸린 IP
summary = []            # 요약 인덱스 역할
for ip, n in Counter(ip for ip, s in web if s >= 500).items():
    if n >= 3: summary.append((ip, "500 에러 몰림"))
for ip, n in Counter(ip for ip, s in web if 400 <= s < 500).items():
    if n >= 10: summary.append((ip, "400 에러 몰림"))
summary += [(ip, "IPS 시그니처") for ip in ips_hits]
by_ip = {}
for ip, what in summary:
    by_ip.setdefault(ip, []).append(what)
for ip, whats in sorted(by_ip.items()):
    print(ip, {1: "info", 2: "warning"}.get(len(whats), "critical"), "/".join(whats))
# 1.1.1.1 critical 500 에러 몰림/400 에러 몰림/IPS 시그니처
# 10.0.0.5 info 500 에러 몰림
